import numpy as np
from PIL import Image
for c in ['top','oblique']:
 d=np.load('/app/output/depth_'+c+'.npy')[0]
 if c=='top': x=np.clip((1.67-d)*200,0,255).astype('uint8')
 else: x=np.clip((3.5-d)*60,0,255).astype('uint8')
 Image.fromarray(x).resize((960,720)).save('/app/output/depthvis_'+c+'.png')
PY

